// Packages:
// - ModelContextProtocol
// - Microsoft.Extensions.DependencyInjection
// - Microsoft.Extensions.Logging
// - Microsoft.AspNetCore.Authentication.JwtBearer (optional)

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol;

var builder = WebApplication.CreateBuilder(args);

// Configuration from appsettings.json and environment variables
builder.Services.AddMcpServer(options =>
{
    options.ServerName = builder.Configuration["Mcp:ServerName"] ?? "order-service-mcp";
    options.ServerVersion = builder.Configuration["Mcp:ServerVersion"] ?? "1.0.0";
    options.SessionTimeout = TimeSpan.FromMinutes(5);
})
.AddToolsFromAssembly(typeof(OrderTools).Assembly)
.AddToolsFromAssembly(typeof(CustomerTools).Assembly)
.WithHttpTransport(options =>
{
    options.Path = "/mcp";
    options.RequireHttps = !builder.Environment.IsDevelopment();
});

// Structured logging
builder.Logging.ClearFilters();
builder.Logging.AddConsole();
builder.Logging.SetMinimumLevel(LogLevel.Information);

// Health checks for production readiness
builder.Services.AddHealthChecks()
    .AddCheck("mcp", new McpServerHealthCheck());

var app = builder.Build();

// Middleware pipeline
app.UseHttpsRedirection();
app.UseAuthentication();
app.UseAuthorization();

app.MapMcp("/mcp");

// Health and readiness endpoints
app.MapHealthChecks("/health/live");
app.MapHealthChecks("/health/ready");

// Expected startup logs:
// [INFO] MCP server 'order-service-mcp' v1.0.0 started
// [INFO] Tools loaded from assemblies: OrderTools, CustomerTools
// [INFO] HTTP transport listening on /mcp (HTTPS required)
app.Run();
